WITH release_scope AS MATERIALIZED ( SELECT member.package_version FROM catalog.effective_release_packages AS member WHERE member.tenant_id = $1 AND member.effective_release_id = $6 AND member.package_id = $2 ), selected AS MATERIALIZED ( SELECT wiring.version, $6::int AS effective_release_id, release_scope.package_version, wiring.graph_json, wiring.wiring_hash FROM release_scope JOIN catalog.wirings AS wiring ON wiring.tenant_id = $1 AND wiring.package_id = $2 AND wiring.package_version = release_scope.package_version WHERE wiring.tenant_id = $1 AND wiring.wiring_id = $4 AND wiring.version = $5 AND wiring.wiring_hash = $7 AND $3::text <> '' ), candidate_nodes AS MATERIALIZED ( SELECT node.key AS node_id, component.component_digest, component.component IS NOT NULL AS component_admitted FROM selected CROSS JOIN LATERAL jsonb_each( CASE WHEN jsonb_typeof(selected.graph_json -> 'nodes') = 'object' THEN selected.graph_json -> 'nodes' ELSE '{}'::jsonb END ) AS node LEFT JOIN catalog.component_library AS component ON component.tenant_id = $1 AND component.package_id = $2 AND component.package_version = selected.package_version AND component.component = node.value ->> 'component' AND component.interface_version = node.value ->> 'interface-version' AND component.operations ? (node.value ->> 'operation') ), node_summary AS MATERIALIZED ( SELECT count(*) AS node_count, count(*) FILTER (WHERE NOT component_admitted) AS invalid_node_count FROM candidate_nodes ), requirements AS MATERIALIZED ( SELECT requirement.component_digest, requirement.store_alias, requirement.requirement_hash FROM (SELECT DISTINCT component_digest FROM candidate_nodes WHERE component_admitted) AS candidate_component JOIN catalog.connection_requirements AS requirement ON requirement.tenant_id = $1 AND requirement.component_digest = candidate_component.component_digest ), resolved_requirements AS MATERIALIZED ( SELECT requirement.component_digest, requirement.store_alias, requirement.requirement_hash, binding.instance_id, instance.revision AS instance_revision, instance.requirement_type, instance.contract, binding.validation_hash, generation.generation, generation.definition_hash, generation.credential_set_handle FROM requirements AS requirement JOIN catalog.connection_bindings AS binding ON binding.tenant_id = $1 AND binding.effective_release_id = $6 AND binding.component_digest = requirement.component_digest AND binding.store_alias = requirement.store_alias AND binding.environment = $3 AND binding.binding_status = 'active' AND binding.validation_status = 'valid' JOIN catalog.connection_instances AS instance ON instance.tenant_id = binding.tenant_id AND instance.environment = binding.environment AND instance.instance_id = binding.instance_id AND instance.lifecycle_status = 'enabled' AND instance.active_generation IS NOT NULL JOIN catalog.connection_generations AS generation ON generation.tenant_id = instance.tenant_id AND generation.environment = instance.environment AND generation.instance_id = instance.instance_id AND generation.generation = instance.active_generation ), binding_world AS MATERIALIZED ( SELECT count(requirement.component_digest) AS requirement_count, count(resolved.component_digest) AS resolved_count, COALESCE(jsonb_agg( jsonb_build_object( 'component-digest', resolved.component_digest, 'store-alias', resolved.store_alias, 'requirement-hash', resolved.requirement_hash, 'instance-id', resolved.instance_id, 'instance-revision', resolved.instance_revision, 'requirement-type', resolved.requirement_type, 'contract', resolved.contract, 'validation-hash', resolved.validation_hash, 'generation', resolved.generation, 'definition-hash', resolved.definition_hash, 'credential-set-handle', resolved.credential_set_handle ) ORDER BY resolved.component_digest, resolved.store_alias ) FILTER (WHERE resolved.component_digest IS NOT NULL), '[]'::jsonb) AS binding_world_json FROM requirements AS requirement LEFT JOIN resolved_requirements AS resolved USING (component_digest, store_alias) ) SELECT selected.version, selected.effective_release_id, selected.package_version, selected.graph_json::text, selected.wiring_hash, COALESCE( jsonb_agg( jsonb_build_object( 'scope', jsonb_build_object( 'tenant-id', $1::text, 'package-id', $2::text, 'package-version', component.package_version ), 'component', component.component, 'interface-version', component.interface_version, 'operations', component.operations, 'component-digest', component.component_digest, 'imports', component.imports, 'imports-fingerprint', component.imports_fingerprint, 'effects', component.effects ) ORDER BY component.component, component.interface_version ) FILTER (WHERE component.component IS NOT NULL), '[]'::jsonb )::text AS components, node_summary.node_count, node_summary.invalid_node_count, binding_world.requirement_count, binding_world.resolved_count, binding_world.binding_world_json::text FROM selected CROSS JOIN node_summary CROSS JOIN binding_world LEFT JOIN catalog.component_library AS component ON component.tenant_id = $1 AND component.package_id = $2 AND component.package_version = selected.package_version AND EXISTS ( SELECT 1 FROM jsonb_each(selected.graph_json -> 'nodes') AS node(node_id, definition) WHERE definition ->> 'component' = component.component AND definition ->> 'interface-version' = component.interface_version AND component.operations ? (definition ->> 'operation') ) GROUP BY selected.version, selected.effective_release_id, selected.package_version, selected.graph_json, selected.wiring_hash, node_summary.node_count, node_summary.invalid_node_count, binding_world.requirement_count, binding_world.resolved_count, binding_world.binding_world_json
